// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.automationimport android.view.accessibility.AccessibilityNodeInfo/** * NOUS — UI Tree Snapshot (Module 9 v1 — Step 9.2). * * A serializable representation of the Android accessibility node tree. * * ## Why this exists * * [AccessibilityNodeInfo] objects are recycled by the Android framework — * they cannot be held across threads or stored. This snapshot class extracts * the relevant data into plain Kotlin data classes that are safe to pass * to the LLM (Module 4) for screen summarization. * * ## Tree Traversal (REAL Android API) * * The [from] factory traverses the real [AccessibilityNodeInfo] tree using: *  - `getChildCount()` + `getChild(i)` — real child node iteration *  - `getText()` — real text content *  - `getClassName()` — real view class (Button, EditText, etc.) *  - `getViewIdResourceName()` — real view ID (API 18+) *  - `isClickable()` / `isFocusable()` / `isEnabled()` — real properties *  - `getBoundsInScreen(rect)` — real screen coordinates * * ## Privacy * *  - Password fields (`isPassword=true`) are EXCLUDED — text is set to null *  - Banking app content is never snapshotted (handled by NousAccessibilityService blacklist) *  - Snapshot is RAM-only — never persisted to disk * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Step 9.2: UiTreeSnapshot</a> */data class UiTreeSnapshot(    val packageName: String,    val windowTitle: String?,    val nodes: List<UiNodeSnapshot>,    val timestampMs: Long,) {    /** Total node count in the tree. */    val nodeCount: Int get() = nodes.size    /** Count of clickable nodes (buttons, links). */    val clickableNodeCount: Int get() = nodes.count { it.isClickable }    /** Count of text nodes. */    val textNodeCount: Int get() = nodes.count { it.text != null }    /** Get all clickable nodes (for "find buttons" queries). */    val clickableNodes: List<UiNodeSnapshot> get() = nodes.filter { it.isClickable }    /** Get all text content concatenated (for OCR-like screen reading). */    val allText: String        get() = nodes.mapNotNull { it.text }.joinToString(" ")    /**     * Find nodes by text (case-insensitive).     */    fun findByText(searchText: String): List<UiNodeSnapshot> =        nodes.filter { it.text?.contains(searchText, ignoreCase = true) == true }    /**     * Find nodes by view ID.     */    fun findByViewId(viewId: String): List<UiNodeSnapshot> =        nodes.filter { it.viewId == viewId }    /**     * Human-readable summary (for TTS + LLM input).     */    fun toSummaryString(): String = buildString {        append("Package: $packageName")        windowTitle?.let { append(", Window: $it") }        append(", Nodes: $nodeCount (${clickableNodeCount} clickable)")        val texts = nodes.mapNotNull { it.text }.take(10)        if (texts.isNotEmpty()) {            append(", Text: ${texts.joinToString(" | ")}")        }    }    companion object {        /**         * Create a snapshot from a REAL [AccessibilityNodeInfo] root.         *         * Traverses the entire node tree recursively, extracting safe data         * (no raw AccessibilityNodeInfo references held after return).         *         * @param rootNode the root node from `rootInActiveWindow`.         * @param packageName the package name of the active window.         * @param windowTitle optional window title.         * @return the serialized [UiTreeSnapshot], or null if root is null.         */        fun from(            rootNode: AccessibilityNodeInfo?,            packageName: String,            windowTitle: String? = null,        ): UiTreeSnapshot? {            if (rootNode == null) return null            val nodes = mutableListOf<UiNodeSnapshot>()            traverseNode(rootNode, 0, nodes)            return UiTreeSnapshot(                packageName = packageName,                windowTitle = windowTitle,                nodes = nodes,                timestampMs = System.currentTimeMillis(),            )        }        /**         * Recursively traverse a node + its children (REAL Android API).         */        private fun traverseNode(            node: AccessibilityNodeInfo,            depth: Int,            output: MutableList<UiNodeSnapshot>,        ) {            // Extract safe data from the node.            val bounds = android.graphics.Rect()            node.getBoundsInScreen(bounds)            // Privacy: skip password field text.            val text = if (node.isPassword) {                null  // NEVER read password field content            } else {                node.text?.toString()            }            val snapshot = UiNodeSnapshot(                text = text,                className = node.className?.toString(),                viewId = node.viewIdResourceName,                isClickable = node.isClickable,                isFocusable = node.isFocusable,                isEnabled = node.isEnabled,                isPassword = node.isPassword,                boundsLeft = bounds.left,                boundsTop = bounds.top,                boundsRight = bounds.right,                boundsBottom = bounds.bottom,                depth = depth,            )            output.add(snapshot)            // Recurse into children (REAL Android API).            val childCount = node.childCount            for (i in 0 until childCount) {                val child = node.getChild(i) ?: continue                traverseNode(child, depth + 1, output)            }        }    }}/** * One node in the UI tree snapshot (plain data, no Android references). */data class UiNodeSnapshot(    val text: String?,    val className: String?,    val viewId: String?,    val isClickable: Boolean,    val isFocusable: Boolean,    val isEnabled: Boolean,    val isPassword: Boolean,    val boundsLeft: Int,    val boundsTop: Int,    val boundsRight: Int,    val boundsBottom: Int,    val depth: Int,) {    /** Node width in pixels. */    val width: Int get() = boundsRight - boundsLeft    /** Node height in pixels. */    val height: Int get() = boundsBottom - boundsTop    /** Center X coordinate. */    val centerX: Int get() = (boundsLeft + boundsRight) / 2    /** Center Y coordinate. */    val centerY: Int get() = (boundsTop + boundsBottom) / 2    /** True if this node has text content. */    val hasText: Boolean get() = text != null && text.isNotBlank()    /** Human-readable description. */    val description: String        get() = buildString {            append(className?.substringAfterLast('.') ?: "View")            text?.let { append(" \"$it\"") }            viewId?.let { append(" [$it]") }            if (isClickable) append(" (clickable)")            if (!isEnabled) append(" (disabled)")        }}